     "كانوا يحرسون معرفة سرية، غير علنية، مرتبطة بالسحر.",
     "كانوا يدوّنون الأساطير ويوقّعون حكاياتهم الخاصة.",
     "كانوا يتحقّقون من الأساطير بملاحظة الطبيعة بعناية."
